create table public.wave_calculation_links (token_hash text primary key check (length(token_hash)=64), user_id uuid not null references public.wave_calculation_owners(user_id) on delete cascade, created_at timestamptz not null default now(), revoked_at timestamptz); alter table public.wave_calculation_links enable row level security; revoke all on public.wave_calculation_links from public, anon, authenticated; grant select, insert, update, delete on public.wave_calculation_links to service_role;
